+static char *
+alnumerize(char *name)
+{
+	char *r = name;
+	char *w = name;
+	char c;
+
+	for (;(c = g_ascii_tolower(*r)); r++) {
+		if (c == '-') {
+			*(w++) = '_';
+		}
+		else if (g_ascii_isalnum(c) || c == '_' || c == '.') {
+			*(w++) = c;
+		}
+	}
+
+	*w = '\0';
+
+	return name;
+}
